import { test } from 'node:test';
import assert from 'node:assert/strict';
import { combinarTurmas } from './solution.mjs';

test('junta duas listas em uma só', () => {
  assert.deepEqual(combinarTurmas(['Ana'], ['Beto', 'Caio']), ['Ana', 'Beto', 'Caio']);
});

test('junta três ou mais listas, na ordem', () => {
  assert.deepEqual(combinarTurmas([1], [2, 3], [4]), [1, 2, 3, 4]);
});

test('lista vazia no meio não atrapalha', () => {
  assert.deepEqual(combinarTurmas([], [1, 2]), [1, 2]);
});

test('recusa argumento que não é lista', () => {
  assert.throws(() => combinarTurmas([1], '2,3'));
});

solutionCode:
export function combinarTurmas(...turmas) {
  for (const turma of turmas) {
    if (!Array.isArray(turma)) {
      throw new Error('cada turma precisa ser uma lista');
    }
  }
  return [].concat(...turmas);
}
